const data={
	header:{
		logo: "logo.png",
		navi:[
			{
				depth1: "Abuot Us",
				depth2: ["기업소개", "연혁", "고운세상", "글로벌 네트워크"]
			},
			{
				depth1: "Brands",
				depth2: ["Dr.G", "스킨 솔루션"]
			},
			{
				depth1: "Sustainability",
				depth2: ["sustainability reports", "윤리경영", "인권정책"]
			},
			{
				depth1: "News",
				depth2: ["고운이야기", "공지사항"]
			},
			{
				depth1: "Careers"
			},
			{
				depth1: "Contact"
			}
		],
		img:{
			search: "gnb-search.png"
		},
		mobile:{
			h4:"(주) 고운세상 코스메틱",
			li:[
				"주소 : 경기도 성남시 분당구 분당로 55 퍼스트타워 11F",
				"대표이사 : 이주호",
				"개인정보관리책임자 : 박상준",
				"대표전화 : 031-724-9000",
				"팩스 : 031-701-9215",
				"사업자등록번호 : 209-81-23948"
			]
		},
		sns:["gnb-sns04.png", "gnb-sns01.png", "gnb-sns02.png", "gnb-sns03.png"]
	},
	main:{
		img:{
			pc:"main_pc.jpg",
			mo:"main_mo.jpg",
			go:"go-btn.png"
		}
	},
	sec1:{
		img:"DRG.jpg",
		text:{
			h4:"My Skin Mentor <br/> Dr.G",
			p:[
				"피부고민, 바르게 답하다. ",
				"고운세상코스메틱의 대표 더마코스메틱 브랜드 닥터지(Dr.G)는",
				"피부고민에 대한 진심 어린 공감과 피부과학을",
				"기반으로 건강한 아름다움을 추구합니다.",
				"수만 건의 피부고민 데이터를 바탕으로 피부 타입 별 진단과",
				"솔루션을 제공하며, 민감성 피부도 안심하고 사용할 수 있는",
				"제품을 개발하는 '정통 피부과학 브랜드'입니다."
			]
		}
	}

}

export default data;
